begin;

update public.catalog_state c
set data = jsonb_set(
  jsonb_set(
    c.data,
    '{testers}',
    coalesce((
      select jsonb_agg(t.value order by t.ordinality)
      from jsonb_array_elements(coalesce(c.data -> 'testers','[]'::jsonb)) with ordinality as t(value, ordinality)
      where t.value ->> 'id' not in ('t051','t040','t023','t015','t006')
    ), '[]'::jsonb)
    || coalesce((
      select jsonb_agg(n.value order by n.ordinality)
